const SIDES=[['север','С',0],['северо-восток','СВ',45],['восток','В',90],['юго-восток','ЮВ',135],['юг','Ю',180],['юго-запад','ЮЗ',225],['запад','З',270],['северо-запад','СЗ',315]];
