 SIDES.forEach(([n,a,d])=>{const r=d*Math.PI/180;s+=TX(cx+Math.sin(r)*(R+22),cy-Math.cos(r)*(R+22)+5,a,{fs:d%90?11:14,c:a==='С'?'var(--bad)':'var(--ink)'});});
 s+=LN(cx,cy,cx,cy-R+20,{c:'var(--bad)',sw:2,dash:'5 4'});
 if(o.az!=null){const r=o.az*Math.PI/180;s+=ARR(cx,cy,cx+Math.sin(r)*(R-6),cy-Math.cos(r)*(R-6),{c:'var(--accent-ink)',sw:3.5,hs:12});
  if(o.arc!==false&&o.az>0){const a1=-Math.PI/2,a2=r-Math.PI/2;const rr=34;s+=PATH(`M${cx},${cy-rr} A${rr},${rr} 0 ${o.az>180?1:0} 1 ${r2(cx+rr*Math.cos(a2))},${r2(cy+rr*Math.sin(a2))}`,{s:'var(--hl)',sw:3});}
  if(o.target)s+=TX(cx+Math.sin(r)*(R-2)+(Math.sin(r)>=0?8:-8),cy-Math.cos(r)*(R-2),o.target,{fs:16,a:Math.sin(r)>=0?'start':'end'});}
 s+=CIR(cx,cy,4,{f:'var(--ink)'});
