 if(scale){const m=scale/100;const lab=v=>v>=1000?N(v/1000)+' км':N(v)+' м';const q=2*px;for(let i=0;i<=4;i++){s+=LN(14+i*q,96,14+i*q,104,{sw:1.2});if(i<4)s+=RECT(14+i*q,98,q,4,{f:i%2?'var(--card)':'var(--fig)',s:'var(--fig)',sw:0.6});s+=TX(14+i*q,118,i===0?'0':lab(m*2*i),{fs:9.5,wt:500});}s+=TX(14+4*q+12,104,'линейный',{fs:10,a:'start',c:'var(--muted)'});}
