 for(let i=0;i<=10;i++)s+=LN(i*C,0,i*C,240,{sw:0.5,c:'var(--muted)',op:0.6});for(let j=0;j<=8;j++)s+=LN(0,j*C,300,j*C,{sw:0.5,c:'var(--muted)',op:0.6});
 objs.forEach(b=>{s+=TX(b.x*C,b.y*C+7,b.ic,{fs:20})+TX(b.x*C,b.y*C+22,b.n,{fs:10,halo:2});});
