/* L1 */
G(1,()=>CH('Что такое <b>азимут</b>?','Угол между направлением на север и направлением на предмет, отсчитанный по часовой стрелке',['Угол между направлением на юг и на предмет против часовой стрелки','Расстояние до предмета в метрах','Высота предмета над уровнем моря'],{
 short:'Азимут — от севера по часовой.',explain:'<b>Азимут</b> — угол от направления <b>на север</b> до направления на предмет, <b>по часовой стрелке</b>; от 0° до 360°.',explain2:'Представь часы: 12 часов — север. Стрелка поворачивается по часовой — это и есть азимут.'}),{rule:true});
G(1,()=>{const s=pick(SIDES);
 return NUM(s[2],{q:`Какой азимут у направления на <b>${s[0]}</b>? Ответ — в градусах.`,short:`${cap(s[0])} — ${s[2]}°.`,explain:`От севера по часовой стрелке: С — 0°, СВ — 45°, В — 90°, ЮВ — 135°, Ю — 180°, ЮЗ — 225°, З — 270°, СЗ — 315°. ${cap(s[0])} — <b>${s[2]}°</b>.`,
  explain2:'Каждая следующая сторона по часовой стрелке — плюс 45°. Начни с севера (0°) и считай.'});});
G(1,()=>{const a=pick([0,30,45,60,90,120,135,150,180,210,225,240,270,300,315,330]);const s=sideOf(a);const exact=a%45===0;
 return CH(`🧭 Азимут — <b>${a}°</b>. В какую сторону (или ближе всего к какой стороне) нужно идти?`,cap(s[0]),sample(SIDES.filter(x=>x!==s).map(x=>cap(x[0])),3),{pic:figCompass({az:a}),short:`${a}° → ${s[0]}.`,
  explain:`Отсчитываем от севера по часовой стрелке ${a}°. ${exact?`Это ровно <b>${s[0]}</b>.`:`Ближайшая сторона — <b>${s[0]}</b> (${s[2]}°).`}`,explain2:'Подсказки: 90° — восток (четверть круга), 180° — юг (половина), 270° — запад (три четверти).'});});
G(1,()=>{const a=pick([20,40,60,80,100,110,130,160,200,230,250,280,300,340]);const opts=[a,(360-a)%360,(a+180)%360,(a+90)%360];if(new Set(opts).size<4)return null;
 return CH('🧭 По рисунку определи азимут на флажок (шкала — через 10°, цифры — через 30°).',a+'°',opts.slice(1).map(x=>x+'°'),{pic:figCompass({az:a,target:'🚩'}),short:`Азимут ${a}°.`,
  explain:`От северного направления (пунктир) по часовой стрелке до стрелки на флажок — <b>${a}°</b>. Ответ ${(360-a)%360}° — если ошибочно считать против часовой, ${(a+180)%360}° — это обратное направление.`,explain2:'Положи палец на «0°» сверху и веди по часовой стрелке до стрелки, считая деления по 10°.'});});

/* L2 — масштаб */
G(2,()=>CH('Как перевести численный масштаб в именованный в <b>метрах</b>?','Убрать у числа два нуля (в 1 м 100 см)',['Убрать три нуля','Убрать пять нулей','Умножить число на 100'],{
 short:'Два нуля — метры, пять нулей — километры.',explain:'В 1 м — 100 см, поэтому чтобы перевести сантиметры в метры, делим на 100: <b>убираем два нуля</b>. Для километров — пять нулей (в 1 км 100 000 см).',explain2:'1 : 25 000 → 25 000 см → 250 м (два нуля убрали).'}),{rule:true});
G(2,()=>{const sc=pick([1000,2000,5000,10000,20000,25000,50000,100000,200000,250000,500000,1000000,2500000,5000000]);const m=sc/100;const km=m>=1000;
 return CH(`Переведи численный масштаб <b>1 : ${N(sc).replace(/(\d)(?=(\d{3})+$)/g,'$1 ')}</b> в именованный.`,km?`в 1 см ${N(m/1000)} км`:`в 1 см ${N(m)} м`,[km?`в 1 см ${N(m)} км`:`в 1 см ${N(m/10)} м`,km?`в 1 см ${N(m/100)} км`:`в 1 см ${N(m*10)} м`,km?`в 1 см ${N(m*10)} м`:`в 1 см ${N(sc)} м`],{
  short:`${N(sc)} см = ${km?N(m/1000)+' км':N(m)+' м'}.`,explain:`1 см на карте = ${N(sc)} см на местности. Убираем два нуля — метры: ${N(m)} м${km?`; ещё три нуля — километры: ${N(m/1000)} км`:''}.`,
  explain2:`Помни: 100 см = 1 м, 1000 м = 1 км. ${N(sc)} : 100 = ${N(m)} м${km?`, ${N(m)} : 1000 = ${N(m/1000)} км`:''}.`});});
G(2,()=>{const m=pick([10,50,100,200,250,500,1000,2000,5000,10000]);const sc=m*100;const t=m>=1000?`${N(m/1000)} км`:`${N(m)} м`;
 return NUM(sc,{q:`Именованный масштаб: «в 1 см ${t}». Запиши численный масштаб: 1 : <b>?</b> (впиши число).`,short:`1 : ${N(sc)}.`,
  explain:`${t} = ${N(m)} м = ${N(sc)} см (в 1 м 100 см). Значит, <b>1 : ${N(sc)}</b>.`,explain2:'Переводим всё в сантиметры: метры × 100.'});});
