/* L3 — расчёты */
G(3,()=>{const sc=pick([1000,2000,5000,10000,25000,50000,100000,1000000]),cm=pick([2,3,4,5,6,7,8,1.5,2.5,3.5,4.5]);const m=sc/100*cm;const km=m>=1000&&sc>=100000;
 return NUM(km?m/1000:m,{q:`📏 На плане масштаба 1 : ${N(sc)} расстояние между точками — <b>${N(cm)} см</b>. Каково расстояние на местности? Ответ — в ${km?'километрах':'метрах'}.`,pic:figRuler(cm,null),
  short:`${N(cm)} · ${N(sc/100)} = ${N(m)} м${km?` = ${N(m/1000)} км`:''}.`,explain:`<b>Шаг 1.</b> Именованный масштаб: в 1 см ${N(sc/100)} м.<br><b>Шаг 2.</b> ${M(`${N(cm)} · ${N(sc/100)} = ${N(m)} м`)}${km?` = <b>${N(m/1000)} км</b>`:''}.`,
  explain2:`Каждый сантиметр — это ${N(sc/100)} м. Сантиметров ${N(cm)} — значит, ${N(cm)} раз по ${N(sc/100)} м.`});});
G(3,()=>{const sc=pick([1000,2000,5000,10000,20000,50000]);const per=sc/100;const cm=pick([2,3,4,5,6,8,1.5,2.5]);const m=per*cm;
 return NUM(cm,{q:`Расстояние на местности — ${N(m)} м. Сколько сантиметров оно займёт на плане масштаба 1 : ${N(sc)}?`,short:`${N(m)} : ${N(per)} = ${N(cm)} см.`,
  explain:`В 1 см — ${N(per)} м. ${M(`${N(m)} : ${N(per)} = ${N(cm)} см`)}.`,explain2:`Сколько раз по ${N(per)} м помещается в ${N(m)} м? Столько и сантиметров.`});});
