function onTheory(root){
 const a=root.querySelector('#w-az');
 if(a){a.innerHTML=`<b>🧭 Компас: поверни стрелку</b>${SL('aA','Азимут:',0,359,1,60)}<div id="aP" class="fig"></div><div id="aT" style="text-align:center;line-height:1.6"></div>`;
  const g=id=>a.querySelector('#'+id);const u=()=>{const v=+g('aA').value;g('aAo').textContent=v+'°';const s=sideOf(v);g('aP').innerHTML=figCompass({az:v,target:'🚩'});g('aT').innerHTML=`Направление ${v%45===0?'— ровно':'ближе всего к'} <span class="out">${s[0]} (${s[1]})</span><br><span class="small">Обратный азимут: ${v<180?v+180:v-180}°</span>`;};
  g('aA').oninput=u;u();}
 const s=root.querySelector('#w-scale');
 if(s){const SC=[1000,5000,10000,25000,50000,100000,1000000];s.innerHTML=`<b>📏 Переводчик масштаба</b>${BTNS(SC.map(x=>['sc'+x,'1 : '+N(x)]))}${SL('sL','Отрезок на карте:',0.5,10,0.5,4)}<div id="sP" class="fig"></div><div id="sT" style="text-align:center;line-height:1.7"></div>`;
  let sc=25000;const g=id=>s.querySelector('#'+id);const u=()=>{const L=+g('sL').value;g('sLo').textContent=N(L)+' см';const m=sc/100;const d=m*L;const lab=v=>v>=1000?N(v/1000)+' км':N(v)+' м';
   g('sP').innerHTML=figRuler(L,sc);g('sT').innerHTML=`1 : ${N(sc)} → убираем два нуля → <b>в 1 см ${lab(m)}</b><br>${N(L)} см · ${lab(m)} = <span class="out">${lab(d)}</span> на местности`;setBtns(s,SC.map(x=>'sc'+x),'sc'+sc);};
  SC.forEach(x=>{g('sc'+x).onclick=()=>{sc=x;u();};});g('sL').oninput=u;u();}
 const h=root.querySelector('#w-hill');
 if(h){h.innerHTML=`<b>⛰ Холм: двигай точку по плану</b>${SL('hX','Положение:',40,282,1,110)}<div id="hP" class="fig"></div><div id="hT" style="text-align:center;line-height:1.6"></div>`;
  const g=id=>h.querySelector('#'+id);const u=()=>{const x=+g('hX').value;g('hXo').textContent='';const hh=hillH(x);g('hP').innerHTML=figHill({x});g('hT').innerHTML=`Высота над подножием ≈ <span class="out">${N(rnd(hh,0))} м</span>${hh<0.5?' (подножие)':''}`;};
  g('hX').oninput=u;u();}
}

